(function(){'use strict';
const KEY='safariPocketbookBookings',tabs=[...document.querySelectorAll('[data-booking-tab]')],panels=[...document.querySelectorAll('[data-booking-panel]')],count=document.getElementById('bookingCount'),records=document.getElementById('bookingRecords');
if(!tabs.length)return;
const esc=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const read=()=>{try{const value=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(value)?value:[]}catch(error){return[]}};
const write=value=>localStorage.setItem(KEY,JSON.stringify(value));
const airports=[['GBE','Sir Seretse Khama International Airport','Gaborone','Botswana'],['FRW','Francistown Airport','Francistown','Botswana'],['MUB','Maun Airport','Maun','Botswana'],['BBK','Kasane Airport','Kasane','Botswana'],['JNB','O. R. Tambo International Airport','Johannesburg','South Africa'],['CPT','Cape Town International Airport','Cape Town','South Africa'],['DUR','King Shaka International Airport','Durban','South Africa'],['MQP','Kruger Mpumalanga International Airport','Mbombela','South Africa'],['HDS','Hoedspruit Airport','Hoedspruit','South Africa'],['WDH','Hosea Kutako International Airport','Windhoek','Namibia'],['WVB','Walvis Bay International Airport','Walvis Bay','Namibia'],['LVI','Harry Mwanga Nkumbula International Airport','Livingstone','Zambia'],['LUN','Kenneth Kaunda International Airport','Lusaka','Zambia'],['MFU','Mfuwe Airport','Mfuwe','Zambia'],['HRE','Robert Gabriel Mugabe International Airport','Harare','Zimbabwe'],['VFA','Victoria Falls International Airport','Victoria Falls','Zimbabwe'],['MPM','Maputo International Airport','Maputo','Mozambique'],['BEW','Beira Airport','Beira','Mozambique'],['VNX','Vilankulo Airport','Vilankulo','Mozambique'],['NBO','Jomo Kenyatta International Airport','Nairobi','Kenya'],['WIL','Wilson Airport','Nairobi','Kenya'],['MBA','Moi International Airport','Mombasa','Kenya'],['JRO','Kilimanjaro International Airport','Kilimanjaro','Tanzania'],['DAR','Julius Nyerere International Airport','Dar es Salaam','Tanzania'],['ZNZ','Abeid Amani Karume International Airport','Zanzibar','Tanzania'],['ARK','Arusha Airport','Arusha','Tanzania'],['EBB','Entebbe International Airport','Entebbe','Uganda'],['KGL','Kigali International Airport','Kigali','Rwanda'],['ADD','Addis Ababa Bole International Airport','Addis Ababa','Ethiopia'],['TNR','Ivato International Airport','Antananarivo','Madagascar'],['NOS','Fascene Airport','Nosy Be','Madagascar'],['LLW','Kamuzu International Airport','Lilongwe','Malawi'],['BLZ','Chileka International Airport','Blantyre','Malawi'],['ACC','Kotoka International Airport','Accra','Ghana'],['LOS','Murtala Muhammed International Airport','Lagos','Nigeria'],['ABV','Nnamdi Azikiwe International Airport','Abuja','Nigeria'],['DSS','Blaise Diagne International Airport','Dakar','Senegal'],['CMN','Mohammed V International Airport','Casablanca','Morocco'],['RAK','Marrakesh Menara Airport','Marrakesh','Morocco'],['CAI','Cairo International Airport','Cairo','Egypt'],['ALG','Houari Boumediene Airport','Algiers','Algeria'],['TUN','Tunis–Carthage International Airport','Tunis','Tunisia'],['MRU','Sir Seewoosagur Ramgoolam International Airport','Mauritius','Mauritius'],['SEZ','Seychelles International Airport','Mahé','Seychelles'],['LHR','Heathrow Airport','London','United Kingdom'],['CDG','Charles de Gaulle Airport','Paris','France'],['FRA','Frankfurt Airport','Frankfurt','Germany'],['AMS','Amsterdam Airport Schiphol','Amsterdam','Netherlands'],['DXB','Dubai International Airport','Dubai','United Arab Emirates'],['DOH','Hamad International Airport','Doha','Qatar'],['IST','Istanbul Airport','Istanbul','Türkiye'],['SIN','Singapore Changi Airport','Singapore','Singapore'],['JFK','John F. Kennedy International Airport','New York','United States']].map(([code,name,city,country])=>({code,name,city,country,value:`${city} (${code}) — ${name}`}));
function installAirportPicker(input){const list=document.createElement('div');list.className='airport-suggestions';list.id=`${input.id}Suggestions`;list.setAttribute('role','listbox');list.hidden=true;input.parentElement.classList.add('airport-field');input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-controls',list.id);input.setAttribute('aria-expanded','false');input.insertAdjacentElement('afterend',list);let timer,active=-1,current=[];const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');active=-1};const choose=item=>{input.value=item.value||item.label;input.dataset.airportCode=item.code||'';close();input.dispatchEvent(new Event('change',{bubbles:true}))};const draw=items=>{current=items.slice(0,8);active=-1;list.innerHTML=current.map((item,index)=>`<button type="button" role="option" data-airport-option="${index}"><strong>${esc(item.code||'AIR')}</strong><span>${esc(item.name||item.label)}</span><small>${esc([item.city,item.country].filter(Boolean).join(', '))}${item.live?' · Live map result':''}</small></button>`).join('');list.hidden=!current.length;input.setAttribute('aria-expanded',String(Boolean(current.length)))};async function search(){const q=input.value.trim().toLowerCase();delete input.dataset.airportCode;if(q.length<2){close();return}const local=airports.filter(item=>`${item.code} ${item.name} ${item.city} ${item.country}`.toLowerCase().includes(q)).slice(0,8);draw(local);if(q.length<3||!navigator.onLine||local.length>=8)return;try{const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=6&q=${encodeURIComponent(`${q} airport`)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(response.status);const live=(await response.json()).filter(item=>item.type==='aerodrome'||item.class==='aeroway'||item.category==='aeroway'||/airport/i.test(item.display_name)).map(item=>({label:item.display_name,name:item.name||item.display_name.split(',')[0],city:item.address?.city||item.address?.town||item.address?.state,country:item.address?.country,live:true}));const seen=new Set(local.map(item=>item.name.toLowerCase()));draw([...local,...live.filter(item=>!seen.has(item.name.toLowerCase()))])}catch(error){if(!local.length)close()}}input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(search,320)});input.addEventListener('focus',()=>{if(input.value.trim().length>=2)search()});input.addEventListener('keydown',event=>{if(list.hidden)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();active=(active+(event.key==='ArrowDown'?1:-1)+current.length)%current.length;list.querySelectorAll('button').forEach((button,index)=>{button.classList.toggle('active',index===active);button.setAttribute('aria-selected',String(index===active))})}else if(event.key==='Enter'&&active>=0){event.preventDefault();choose(current[active])}else if(event.key==='Escape')close()});list.addEventListener('mousedown',event=>event.preventDefault());list.addEventListener('click',event=>{const option=event.target.closest('[data-airport-option]');if(option)choose(current[Number(option.dataset.airportOption)])});input.addEventListener('blur',()=>setTimeout(close,120))}
['flightFrom','flightTo'].forEach(id=>installAirportPicker(document.getElementById(id)));
function toast(message){const node=document.getElementById('toast');node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),2200)}
function show(name){tabs.forEach(tab=>{const active=tab.dataset.bookingTab===name;tab.classList.toggle('selected',active);tab.setAttribute('aria-selected',String(active))});panels.forEach(panel=>{const active=panel.dataset.bookingPanel===name;panel.hidden=!active;panel.classList.toggle('active',active)});document.querySelector('.booking-shell')?.scrollIntoView({block:'start'})}
tabs.forEach(tab=>tab.addEventListener('click',()=>show(tab.dataset.bookingTab)));
const today=new Date().toISOString().slice(0,10);['flightDepart','flightReturn','stayCheckin','stayCheckout','recordDate'].forEach(id=>document.getElementById(id).min=today);
document.querySelectorAll('[data-go="bookings"]').forEach(button=>button.addEventListener('click',()=>{try{const trip=JSON.parse(localStorage.getItem('safariPocketbookTrip')||'null');if(!trip)return;const destination=trip.countries?.join(', ')||trip.stops?.[0]?.name||'';if(!document.getElementById('flightTo').value)document.getElementById('flightTo').value=destination;if(!document.getElementById('stayDestination').value)document.getElementById('stayDestination').value=destination;if(trip.startDate&&!document.getElementById('flightDepart').value)document.getElementById('flightDepart').value=trip.startDate;if(trip.startDate&&!document.getElementById('stayCheckin').value)document.getElementById('stayCheckin').value=trip.startDate}catch(error){}}));
let selectedDraft=null;
function ensureCheckout(){let dialog=document.getElementById('bookingPreviewDialog');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='bookingPreviewDialog';dialog.className='booking-preview-dialog';dialog.innerHTML='<button class="dialog-close booking-preview-close" type="button" aria-label="Close booking window">×</button><div id="bookingPreviewContent"></div>';document.body.appendChild(dialog);dialog.querySelector('.booking-preview-close').addEventListener('click',()=>dialog.close());return dialog}
function openCheckout(){const dialog=ensureCheckout(),content=dialog.querySelector('#bookingPreviewContent'),draft=selectedDraft;content.innerHTML=`<div class="prototype-banner"><strong>BOOKING</strong><span>Booking summary</span></div><div class="checkout-steps"><b>1 Review</b><span>2 Traveller</span><span>3 Payment</span></div><section class="checkout-summary"><p>${esc(draft.kind==='flight'?'FLIGHT':'ACCOMMODATION')}</p><h2>${esc(draft.title)}</h2><small>${esc(draft.detail)}</small><div><strong>Live price unavailable</strong><span>No verified fare or room rate was returned for this selection.</span></div></section><form id="travellerPreviewForm" class="traveller-preview"><h3>Traveller details</h3><label>Title<select required><option>Mr</option><option>Ms</option><option>Mrs</option><option>Dr</option></select></label><label>First name<input required autocomplete="given-name"></label><label>Last name<input required autocomplete="family-name"></label><label>Email<input required type="email" autocomplete="email"></label><label>Phone<input required type="tel" autocomplete="tel"></label><button type="submit">Continue to review</button><p>Details remain on this screen and are not transmitted or saved.</p></form><section class="payment-preview"><h3>Payment</h3><p>Payment requires a verified offer with a final total, provider identity and cancellation terms.</p><button type="button" disabled>Select a verified offer</button></section>`;content.querySelector('#travellerPreviewForm').addEventListener('submit',event=>{event.preventDefault();content.querySelector('.checkout-steps').innerHTML='<span>✓ Review</span><b>2 Traveller</b><span>3 Payment</span>';content.querySelector('.payment-preview').scrollIntoView({behavior:'smooth',block:'start'});toast('Booking journey reviewed. No booking or payment was made.')});if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function renderPrototype(kind,data){const panel=document.querySelector(`[data-booking-panel="${kind}"]`),old=panel.querySelector('.booking-demo-results');old?.remove();const result=document.createElement('section');result.className='booking-demo-results';const options=kind==='flight'?[['Direct route layout','Direct route and schedule details'],['Best-value layout','Fare and itinerary comparison'],['Flexible route layout','Alternative times and connections']]:[[`${data.type} layout`,'Property details and verified location'],['Alternative stay layout','Room types, amenities and cancellation terms'],['Nearby option layout','Map distance, transfers and rate details']];result.innerHTML=`<div class="demo-result-head"><div><p class="eyebrow dark">SEARCH RESULTS</p><h3>${kind==='flight'?`${esc(data.from)} → ${esc(data.to)}`:`${esc(data.destination)} stays`}</h3></div><span>Search results</span></div>${options.map((option,index)=>`<article><div class="demo-result-mark">${kind==='flight'?'✈':'⌂'}</div><div><small>OPTION ${index+1}</small><h4>${esc(option[0])}</h4><p>${esc(option[1])}</p><strong>Price unavailable</strong></div><button type="button" data-preview-option="${index}">Select</button></article>`).join('')}`;panel.appendChild(result);result.querySelectorAll('[data-preview-option]').forEach((button,index)=>button.addEventListener('click',()=>{selectedDraft={kind,title:kind==='flight'?`${data.from} to ${data.to}`:`${data.type} in ${data.destination}`,detail:kind==='flight'?`${data.depart}${data.back?` to ${data.back}`:''} · ${data.travellers} traveller(s)`: `${data.checkin} to ${data.checkout} · ${data.guests} guest(s)`,option:index};openCheckout()}));result.scrollIntoView({behavior:'smooth',block:'start'})}
const flightPanel=document.querySelector('[data-booking-panel="flight"]'),stayPanel=document.querySelector('[data-booking-panel="stay"]');flightPanel.querySelector('.booking-heading>p:last-child').textContent='Search and compare flights without leaving African Safari Pocketbook.';stayPanel.querySelector('.booking-heading>p:last-child').textContent='Search lodges, camps and hotels without leaving African Safari Pocketbook.';flightPanel.querySelector('.booking-search').innerHTML='Search flights <span>→</span>';stayPanel.querySelector('.booking-search').innerHTML='Search stays <span>→</span>';flightPanel.querySelector('.booking-disclosure').textContent='Compare schedules, total fares, baggage conditions and ticket rules before selecting a flight.';stayPanel.querySelector('.booking-disclosure').textContent='Compare the full rate, room conditions, location, transfers and cancellation terms before reserving.';
document.getElementById('flightSearchForm').addEventListener('submit',event=>{event.preventDefault();const from=document.getElementById('flightFrom').value.trim(),to=document.getElementById('flightTo').value.trim(),depart=document.getElementById('flightDepart').value,back=document.getElementById('flightReturn').value,travellers=document.getElementById('flightTravellers').value;if(back&&back<depart){toast('Return date must be after departure.');return}renderPrototype('flight',{from,to,depart,back,travellers})});
document.getElementById('staySearchForm').addEventListener('submit',event=>{event.preventDefault();const destination=document.getElementById('stayDestination').value.trim(),checkin=document.getElementById('stayCheckin').value,checkout=document.getElementById('stayCheckout').value,guests=document.getElementById('stayGuests').value,type=document.getElementById('stayType').value;if(checkout<=checkin){toast('Check-out must be after check-in.');return}renderPrototype('stay',{destination,checkin,checkout,guests,type})});
function render(){const items=read();count.textContent=items.length;records.innerHTML=items.length?items.map(item=>`<article><span>${esc(item.type).toUpperCase()}</span><h3>${esc(item.provider)}</h3><p><strong>Reference:</strong> ${esc(item.reference)}${item.date?` · ${esc(item.date)}`:''}</p>${item.details?`<small>${esc(item.details)}</small>`:''}<button type="button" data-delete-booking="${esc(item.id)}" aria-label="Delete booking with ${esc(item.provider)}">Remove</button></article>`).join(''):'<div class="booking-empty"><strong>No confirmed bookings saved.</strong><p>Flight and stay searches do not create records automatically. Add a reference only after confirmation by the provider.</p></div>'}
document.getElementById('bookingRecordForm').addEventListener('submit',event=>{event.preventDefault();const items=read();items.unshift({id:`${Date.now()}-${Math.random().toString(16).slice(2)}`,type:document.getElementById('recordType').value,provider:document.getElementById('recordProvider').value.trim().slice(0,120),reference:document.getElementById('recordReference').value.trim().slice(0,120),date:document.getElementById('recordDate').value,details:document.getElementById('recordDetails').value.trim().slice(0,1000)});write(items);event.target.reset();render();toast('Confirmed booking saved on this device.')});
records.addEventListener('click',event=>{const button=event.target.closest('[data-delete-booking]');if(!button||!confirm('Remove this booking record from the device?'))return;write(read().filter(item=>item.id!==button.dataset.deleteBooking));render();toast('Booking record removed.')});
render();
})();
